select date_trunc('month', start_date) as activity_month, count(*) filter (where plan = 'enterprise') as enterprise_rows, round(sum(monthly_fee) / nullif(count(case when status = 'CANCELLED' then 1 end), 0), 2) as monthly_fee_per_cancelled, count(distinct status) as distinct_status from subscriptions group by rollup (date_trunc('month', start_date)) having round(sum(monthly_fee) / nullif(count(case when status = 'CANCELLED' then 1 end), 0), 2) > 0
